//
// test_v4.c — HOST test bench of protocol v4 (MULTI), ESP32 side.
//
// Compiles and links the REAL MODULE (src/multi.c) against the vectors
// generated by tools/check_v4.py: what is tested is the code that runs on the
// device, not a rewrite of it for the test.
//
//   cd esp32/main/test
//   gcc -I stub -I ../include -Wall -Wextra test_v4.c ../src/multi.c -o test_v4 && ./test_v4
//
// Covers:
//   1. parsing round trip: every field of every vector (proto_ver 0x05),
//      sentinels and limits;
//   2. rejection of invalid packets: magic, version (unknown versions and the
//      v5 0x06, even with a correct CRC), n_samples, length, and EVERY
//      single-bit corruption in EVERY position; v4/v5 routing by proto_ver;
//   3. per-node continuity: new session, total and partial duplicates (write
//      response lost), forward jumps (samples gone to another edge), session
//      change;
//   4. the advertising payload against the vectors;
//   5. the unpacking of the radio telemetry (fields 4-7) against the vectors:
//      moduli, bits of the radio byte, RSSI sign.
//
// WHAT THIS TEST CANNOT PROVE: edge selection, handoff, queue and
// retransmission, which live on the watch and can only be verified in the
// field, and the whole radio behaviour. See docs/guide.md, § "Field
// verification", MULTI variant.
//
#include <stdio.h>
#include <string.h>

#include "multi.h"
#include "protocol_v5.h"   // v5_route_monitor: routing of the APP payload
#include "v4_vectors.h"

static int failures = 0;

#define CHECK(cond, ...) do {                      \
    if (!(cond)) {                                 \
        printf("  [FAIL] " __VA_ARGS__);           \
        printf("\n");                              \
        failures++;                                \
    }                                              \
} while (0)

// ---------------------------------------------------------------------------
// 1. Full parsing
// ---------------------------------------------------------------------------
static void test_parse(void) {
    printf("[1] Parsing of the vectors\n");

    for (int i = 0; i < V4_VECTORS_N; i++) {
        const v4_vec_t *v = &V4_VECTORS[i];
        multi_pkt_t p;

        multi_result_t r = multi_parse(v->bytes, v->len, &p);
        if (r != MULTI_OK) {
            printf("  [FAIL] %s: valid packet REJECTED (%s)\n",
                   v->name, multi_result_name(r));
            failures++;
            continue;
        }

        CHECK(p.node_id == v->node_id, "%s: node %u != %u", v->name, p.node_id, v->node_id);
        CHECK(p.n_samples == v->n_samples, "%s: n %u != %u", v->name, p.n_samples, v->n_samples);
        CHECK(p.session_id == v->session_id, "%s: session %lu != %lu", v->name,
              (unsigned long)p.session_id, (unsigned long)v->session_id);
        CHECK(p.seq_first == v->seq_first, "%s: seq %lu != %lu", v->name,
              (unsigned long)p.seq_first, (unsigned long)v->seq_first);
        CHECK(p.backlog == v->backlog, "%s: backlog %u != %u", v->name, p.backlog, v->backlog);
        CHECK(p.conn_no == v->conn_no, "%s: conn_no %u != %u", v->name, p.conn_no, v->conn_no);

        for (uint8_t s = 0; s < v->n_samples; s++) {
            for (int f = 0; f < PROTO_NFIELDS; f++) {
                CHECK(p.field[s][f] == v->field[s][f], "%s[%u] field %d: 0x%08lX != 0x%08lX",
                      v->name, s, f, (unsigned long)p.field[s][f],
                      (unsigned long)v->field[s][f]);
            }
        }
    }
    printf("    %d vectors examined\n", V4_VECTORS_N);
}

// ---------------------------------------------------------------------------
// 2. Rejection of invalid packets
// ---------------------------------------------------------------------------
static void test_reject(void) {
    printf("[2] Rejection of invalid packets\n");

    const v4_vec_t *v = &V4_VECTORS[1];     // 4 samples: the longest packet
    uint8_t buf[V4V_MAX_LEN];
    multi_pkt_t p;

    memcpy(buf, v->bytes, v->len);
    buf[V4_H_MAGIC] = 0x00;
    CHECK(multi_parse(buf, v->len, &p) == MULTI_ERR_MAGIC, "wrong magic ACCEPTED");

    // No other version must EVER be read as v4 (same magic): neither an
    // unknown version (0x03, 0x04), nor a v5 (0x06, the first 14 bytes of the
    // header are those of v4). CRC recomputed: the rejection must depend on the
    // version, not on the order of the checks.
    const uint8_t old_vers[] = { 0x03, 0x04, V5_VER };
    for (unsigned i = 0; i < sizeof(old_vers); i++) {
        memcpy(buf, v->bytes, v->len);
        buf[V4_H_VER] = old_vers[i];
        uint16_t crc = v3_crc16(buf, v->len - V4_CRC_BYTES);
        buf[v->len - 2] = (uint8_t)(crc >> 8);
        buf[v->len - 1] = (uint8_t)crc;
        CHECK(multi_parse(buf, v->len, &p) == MULTI_ERR_MAGIC,
              "proto_ver 0x%02X ACCEPTED as v4", old_vers[i]);
    }

    // Routing of the APP payload (ble.c): only 0x06 to v5, everything else to
    // v4, which accepts only 0x05 and rejects the other versions (above) with
    // an ATT error. A payload too short to have a proto_ver also goes to v4,
    // which rejects it for its length.
    memcpy(buf, v->bytes, v->len);
    CHECK(!v5_route_monitor(buf, v->len), "0x05 routed to v5");
    buf[V4_H_VER] = V5_VER;
    CHECK(v5_route_monitor(buf, v->len), "0x06 not routed to v5");
    buf[V4_H_VER] = 0x03;
    CHECK(!v5_route_monitor(buf, v->len), "0x03 routed to v5");
    buf[V4_H_VER] = 0x04;
    CHECK(!v5_route_monitor(buf, v->len), "0x04 routed to v5");
    buf[V4_H_VER] = V5_VER;
    CHECK(!v5_route_monitor(buf, 1), "1-byte payload routed to v5");
    CHECK(multi_parse(buf, 1, &p) == MULTI_ERR_LEN, "1-byte payload ACCEPTED by v4");

    memcpy(buf, v->bytes, v->len);
    buf[V4_H_NSAMPLES] = 0;
    CHECK(multi_parse(buf, v->len, &p) == MULTI_ERR_NSAMPLES, "n_samples=0 ACCEPTED");
    buf[V4_H_NSAMPLES] = V4_MAX_SAMPLES + 1;
    CHECK(multi_parse(buf, v->len, &p) == MULTI_ERR_NSAMPLES, "n_samples above the maximum ACCEPTED");

    memcpy(buf, v->bytes, v->len);
    CHECK(multi_parse(buf, v->len - 1, &p) == MULTI_ERR_LEN, "truncated length ACCEPTED");
    CHECK(multi_parse(buf, 3, &p) == MULTI_ERR_LEN, "3-byte packet ACCEPTED");

    // n_samples declares 3 but the bytes are those of 4 samples: length mismatch.
    memcpy(buf, v->bytes, v->len);
    buf[V4_H_NSAMPLES] = 3;
    CHECK(multi_parse(buf, v->len, &p) == MULTI_ERR_LEN, "inconsistent n_samples ACCEPTED");

    // Every bit of every vector, one at a time: no corruption must pass.
    int missed = 0;
    unsigned long total = 0;
    for (int i = 0; i < V4_VECTORS_N; i++) {
        const v4_vec_t *w = &V4_VECTORS[i];
        for (uint32_t pos = 0; pos < w->len; pos++) {
            for (int bit = 0; bit < 8; bit++) {
                memcpy(buf, w->bytes, w->len);
                buf[pos] ^= (uint8_t)(1u << bit);
                if (multi_parse(buf, w->len, &p) == MULTI_OK) { missed++; }
                total++;
            }
        }
    }
    CHECK(missed == 0, "%d single-bit corruptions NOT caught out of %lu", missed, total);
    printf("    %lu single-bit corruptions tried\n", total);
}

// ---------------------------------------------------------------------------
// 3. Per-node continuity
// ---------------------------------------------------------------------------
static multi_pkt_t mk(uint32_t session, uint32_t seq, uint8_t n) {
    multi_pkt_t p;
    memset(&p, 0, sizeof(p));
    p.session_id = session;
    p.seq_first  = seq;
    p.n_samples  = n;
    return p;
}

static void test_track(void) {
    printf("[3] Duplicates and jumps per node\n");
    multi_track_t t;
    multi_pkt_t p;

    multi_track_reset();

    // First packet: new session, even if it does not start from 0 (the watch
    // may have started on another edge).
    p = mk(1000, 40, 1);
    multi_track(&p, &t);
    CHECK(t.new_session && !t.jump && t.first_new == 0, "first packet misclassified");

    // Regular next one.
    p = mk(1000, 41, 1);
    multi_track(&p, &t);
    CHECK(!t.new_session && !t.jump && t.first_new == 0, "41 after 40: misclassified");

    // Same packet sent again (write response lost): all duplicate.
    p = mk(1000, 41, 1);
    multi_track(&p, &t);
    CHECK(t.first_new == 1, "resend of 41: first_new %u != 1", t.first_new);

    // Partial overlap: 41..44 after receiving up to 41.
    p = mk(1000, 41, 4);
    multi_track(&p, &t);
    CHECK(t.first_new == 1 && !t.jump, "41+4 after 41: first_new %u != 1", t.first_new);

    // Forward jump: 45..59 went to another edge.
    p = mk(1000, 60, 2);
    multi_track(&p, &t);
    CHECK(t.jump && t.expected == 45 && t.first_new == 0,
          "jump 45->60 not detected (jump=%d expected=%lu)", t.jump, (unsigned long)t.expected);

    // After the jump the numbering continues from 62.
    p = mk(1000, 62, 1);
    multi_track(&p, &t);
    CHECK(!t.jump && t.first_new == 0, "62 after 60+2: misclassified");

    // An old sample (already passed) is a duplicate, not a backward jump.
    p = mk(1000, 50, 1);
    multi_track(&p, &t);
    CHECK(t.first_new == 1 && !t.jump, "seq 50 after 62: first_new %u", t.first_new);

    // Session change: no comparison with the previous numbering.
    p = mk(2000, 0, 1);
    multi_track(&p, &t);
    CHECK(t.new_session && !t.jump && t.first_new == 0, "new session misclassified");
    p = mk(2000, 1, 1);
    multi_track(&p, &t);
    CHECK(!t.new_session && !t.jump && t.first_new == 0, "seq 1 of the new session misclassified");
}

// ---------------------------------------------------------------------------
// 4. Advertising
// ---------------------------------------------------------------------------
static void test_adv(void) {
    printf("[4] Advertising payload\n");
    for (int i = 0; i < V4_ADVS_N; i++) {
        uint8_t out[V4_ADV_BYTES];
        v4_build_adv(V4_ADVS[i].node_id, V4_ADVS[i].busy != 0, out);
        CHECK(memcmp(out, V4_ADVS[i].payload, V4_ADV_BYTES) == 0,
              "advertising node %u busy=%u differs from the vector",
              V4_ADVS[i].node_id, V4_ADVS[i].busy);
    }
}

// ---------------------------------------------------------------------------
// 5. Radio telemetry (fields 4-7)
// ---------------------------------------------------------------------------
static void test_tel(void) {
    printf("[5] Radio telemetry of fields 4-7\n");
    for (int i = 0; i < V4_TELS_N; i++) {
        const v4_tel_t *x = &V4_TELS[i];
        uint32_t f[PROTO_NFIELDS];
        for (int k = 0; k < PROTO_NFIELDS; k++) { f[k] = PROTO_SENTINEL; }
        f[V4_F_TEL_TIME]  = x->word[0];
        f[V4_F_TEL_LINK]  = x->word[1];
        f[V4_F_TEL_COUNT] = x->word[2];
        f[V4_F_TEL_STATE] = x->word[3];

        v4_telemetry_t t;
        v4_tel_decode(f, &t);
        CHECK(t.t_conn_s == x->t_conn_s && t.t_scan_s == x->t_scan_s &&
              t.t_agg_s == x->t_agg_s && t.tx_chunks == x->tx_chunks,
              "%s: times/chunks %u,%u,%u,%u != %u,%u,%u,%u", x->name,
              t.t_conn_s, t.t_scan_s, t.t_agg_s, t.tx_chunks,
              x->t_conn_s, x->t_scan_s, x->t_agg_s, x->tx_chunks);
        CHECK(t.n_try == x->n_try && t.n_conn == x->n_conn && t.n_ho == x->n_ho &&
              t.n_lost == x->n_lost && t.n_fail == x->n_fail,
              "%s: counters %u,%u,%u,%u,%u != %u,%u,%u,%u,%u", x->name,
              t.n_try, t.n_conn, t.n_ho, t.n_lost, t.n_fail,
              x->n_try, x->n_conn, x->n_ho, x->n_lost, x->n_fail);
        CHECK(t.radio == x->radio && t.scan_on == (x->scan_on != 0) &&
              t.roam_ok == (x->roam_ok != 0),
              "%s: radio %u scan %d roam %d != %u %u %u", x->name,
              t.radio, t.scan_on, t.roam_ok, x->radio, x->scan_on, x->roam_ok);
        CHECK(t.rssi == x->rssi, "%s: rssi %d != %d", x->name, t.rssi, x->rssi);
        CHECK(t.coda == x->coda, "%s: coda %u != %u", x->name, t.coda, x->coda);
    }
    printf("    %d cases examined\n", V4_TELS_N);
}

int main(void) {
    test_parse();
    test_reject();
    test_track();
    test_adv();
    test_tel();

    if (failures) {
        printf("\n[KO] %d checks failed\n", failures);
        return 1;
    }
    printf("\n[OK] all v4 tests passed\n");
    return 0;
}
